#include <Wire.h>
// Scan the I2C bus, then read the MPU-6050's WHO_AM_I register
const int IMU = {{p:address}};

void setup() {
  Serial.begin(115200);
  Wire.begin();                    // SDA and SCL: the same pins as A4 and A5
  Serial.println("Scanning I2C...");
  int found = 0;
  for (int address = 1; address < 127; address++) {
    Wire.beginTransmission(address);
    if (Wire.endTransmission() == 0) {
      Serial.print("Found a device at 0x");
      Serial.println(address, HEX);
      found++;
    }
  }
  Serial.print("Devices found: ");
  Serial.println(found);
}

void loop() {
  Wire.beginTransmission(IMU);
  Wire.write(0x75);                // register 0x75 holds the chip's ID
  Wire.endTransmission(false);
  Wire.requestFrom(IMU, 1);
  if (Wire.available()) {
    Serial.print("WHO_AM_I = 0x");
    Serial.println(Wire.read(), HEX);
  } else {
    Serial.println("No answer");
  }
  delay(1000);
}

